  + ST(3, FNODE(3, 'מה נשאר בסוף?', 'בדרך כלל כלום: fv של 0.', 'יש תשלום גדול בסוף (בלון)? הוא fv, במינוס.'), cls='')
  + ST(4, FNODE(4, 'יש מקדמה?', 'מחסירים אותה מהמחיר במזומן: pv = מחיר פחות מקדמה.', 'אין מקדמה: pv הוא המחיר במזומן כולו.'), cls='')
